        "Sangrąžinis veiksmažodis: ich verlaufe mich, er verläuft sich, verlief sich, hat sich verlaufen. Perfekt sudaromas su haben. Paprastai vartojamas su vieta: im Wald, in der Stadt, in den Bergen.",
